// Versioned Deal Risk lead contract. The idempotencyKey is stable across retries.
const input = $input.item.json;
const lead = input.body ?? input;
const num = (v) => { if (v === null || v === undefined || v === '') return null; const n = Number(String(v).replace(/[^0-9.\-]/g, '')); return Number.isFinite(n) ? n : null; };
const text = (v) => (v ?? '').toString().trim();
const address = text(lead.address); const city = text(lead.city); const state = text(lead.state).toUpperCase(); const zip = text(lead.zip);
const strategyMode = text(lead.strategyMode || 'fix_and_flip').toLowerCase().replace(/\s+/g, '_');
const allowedStrategies = ['fix_and_flip', 'long_term_rental', 'brrrr', 'wholesale'];
const sqft = num(lead.sqft); const yearBuilt = num(lead.yearBuilt); const askingPrice = num(lead.askingPrice);
const monthlyRent = num(lead.monthlyRent); const annualTaxes = num(lead.annualTaxes); const annualInsurance = num(lead.annualInsurance); const monthlyHoa = num(lead.monthlyHoa);
const errors = [];
if (!address) errors.push('address is required'); if (!city) errors.push('city is required'); if (!/^[A-Z]{2}$/.test(state)) errors.push('state must be a 2-letter code'); if (!/^\d{5}(-\d{4})?$/.test(zip)) errors.push('zip must be 5 or 9 digits'); if (!sqft || sqft <= 0) errors.push('sqft must be positive'); if (!yearBuilt || yearBuilt < 1800 || yearBuilt > 2100) errors.push('yearBuilt looks invalid'); if (!askingPrice || askingPrice <= 0) errors.push('askingPrice must be positive'); if (!allowedStrategies.includes(strategyMode)) errors.push('strategyMode must be fix_and_flip, long_term_rental, brrrr, or wholesale');
if (['long_term_rental', 'brrrr'].includes(strategyMode) && (!monthlyRent || monthlyRent <= 0)) errors.push('monthlyRent is required for rental strategies');
if (errors.length) throw new Error('Validation failed: ' + errors.join('; '));
const normalizedAddress = `${address}, ${city}, ${state} ${zip}`.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const idempotencyKey = [normalizedAddress, Math.round(askingPrice), strategyMode].join('|');
const receivedAt = new Date().toISOString();
return { json: { runId: `${normalizedAddress}-${Date.now()}`.slice(0, 100), idempotencyKey, receivedAt, normalizedAddress, address, city, state, zip, oneLineAddress: `${address}, ${city}, ${state} ${zip}`, beds: num(lead.beds), baths: num(lead.baths), sqft, yearBuilt, propertyAgeYears: new Date().getFullYear() - yearBuilt, askingPrice, condition: text(lead.condition || 'unknown').toLowerCase(), notes: text(lead.notes), strategyMode, monthlyRent, annualTaxes, annualInsurance, monthlyHoa, vacancyPct: num(lead.vacancyPct), maintenancePct: num(lead.maintenancePct), holdingMonths: num(lead.holdingMonths) } };
